import {protectedRoute} from '@/lib/http/protected-route';import {database,checkDb,CaptureError} from '@/lib/db/admin';import {z} from 'zod';
export async function GET(request:Request){return protectedRoute(request,'staff',async()=>{const {data,error}=await database().from('vendors').select('*,contacts:vendor_contacts(*)').order('name');checkDb(error);return {vendors:(data||[]).map(v=>({...v.data,id:v.id,name:v.name,created_at:v.created_at,updated_at:v.updated_at,contacts:v.contacts.map((c:{id:string;data:object})=>({...c.data,id:c.id}))}))};});}
export async function POST(request:Request){return protectedRoute(request,'staff',async()=>{const raw=await request.text();if(raw.length>100000)throw new CaptureError('Vendor record is too large.');const body=z.object({id:z.uuid().nullable().optional(),data:z.record(z.string(),z.unknown())}).parse(JSON.parse(raw));const fields=body.data;if(typeof fields.name!=='string'||!fields.name.trim())throw new CaptureError('Vendor name is required.');const contacts=z.array(z.record(z.string(),z.unknown())).max(50).parse(fields.contacts||[]);const {data:id,error}=await database().rpc('save_vendor',{p_id:body.id||null,p_data:fields,p_contacts:contacts});checkDb(error);return {id};});}